                    this.data = jsyaml.load(scriptElement.textContent.trim());
                    if (!this.data || Object.keys(this.data).length === 0) throw new Error('YAML data is invalid or empty.');
                }

                findRootNode() {
                    const rootNodeNames = Object.keys(this.data);
                    if (rootNodeNames.length === 0) throw new Error('YAML data has no root node.');
                    this.rootNode = rootNodeNames[0];
                }

                findField(dataObj, keywords) {
                    if (!dataObj) return null;
                    const fields = Object.keys(dataObj);
                    for (const field of fields) {
                        const lowerField = field.toLowerCase();
                        for (const keyword of keywords) {
                            if (lowerField.includes(keyword)) return field;
                        }
                    }
                    return null;
                }

                renderAll() {
                    const rootData = this.data[this.rootNode];
                    if (!rootData) throw new Error('Root data node is missing.');
                    this.renderHeader(rootData);
                    this.renderVideoData(rootData);
                    this.renderDanmaku(rootData);
                    this.renderCast(rootData);
                    this.renderComments(rootData);
                }

                renderHeader(rootData) {
                    const titleField = this.findField(rootData, ['标题', 'title']);
                    const uploaderField = this.findField(rootData, ['上传者', 'uploader']);
                    const timeField = this.findField(rootData, ['时间', 'time', 'date']);
                    this.elements.title.textContent = titleField ? rootData[titleField] : '无标题';
                    this.elements.uploader.textContent = uploaderField ? rootData[uploaderField] : '未知';
                    this.elements.time.textContent = timeField ? this.formatTime(rootData[timeField]) : '';
                }

                renderVideoData(rootData) {
                    const videoDataField = this.findField(rootData, ['视频数据', 'video']);
                    if (!videoDataField || !rootData[videoDataField]) return;
                    const videoData = rootData[videoDataField];
                    const viewsField = this.findField(videoData, ['播放', 'view']);
                    const likeField = this.findField(videoData, ['点赞', 'like']);
                    const progressField = this.findField(videoData, ['进度', 'progress']);
                    if(viewsField) this.elements.views.textContent = videoData[viewsField];
                    if(likeField) {
                        this.elements.likeRate.textContent = videoData[likeField];
                        this.elements.likeBar.style.width = videoData[likeField];
                    }
                    if(progressField) {
                        const progressText = videoData[progressField];
                        const parts = progressText.replace(/ /g, '').split('/');
                        if (parts.length === 2) {
                            const [curMin, curSec] = parts[0].split(':').map(Number);
                            const [totMin, totSec] = parts[1].split(':').map(Number);
                            if (!isNaN(curMin) && !isNaN(curSec) && !isNaN(totMin) && !isNaN(totSec)) {
                                const curSeconds = curMin * 60 + curSec;
                                const totSeconds = totMin * 60 + totSec;
                                if (totSeconds > 0) {
                                    const percentage = (curSeconds / totSeconds * 100).toFixed(2);
                                    this.elements.progressBar.style.width = `${percentage}%`;
                                }
                            }
                        }
                    }
                }

                renderDanmaku(rootData) {
                    const danmakuField = this.findField(rootData, ['弹幕', 'danmaku']);
                    if (!danmakuField || !Array.isArray(rootData[danmakuField])) return;
                    this.elements.danmaku.innerHTML = '';
                    rootData[danmakuField].forEach((comment, index) => {
                        const danmakuEl = document.createElement('div');
                        danmakuEl.className = 'danmaku-item';
                        danmakuEl.textContent = comment;
                        danmakuEl.style.top = `${Math.random() * 85}%`;
                        const duration = Math.random() * 6 + 7; // 7-13 seconds
                        danmakuEl.style.animationDuration = `${duration}s`;
                        danmakuEl.style.animationDelay = `${Math.random() * duration}s`;
                        this.elements.danmaku.appendChild(danmakuEl);
                    });
                }

                renderCast(rootData) {
                    const castField = this.findField(rootData, ['演职员', 'cast', '角色']);
                    if (!castField || !Array.isArray(rootData[castField])) {
                        this.elements.cast.innerHTML = `<p class="text-center text-gray-500">未找到演职员信息。</p>`;
                        return;
                    }
                    this.elements.cast.innerHTML = '';
                    rootData[castField].forEach(item => {
                        const roleField = this.findField(item, ['角色', 'role']);
                        const characterData = roleField ? item[roleField] : item;
                        const nameField = this.findField(characterData, ['名', 'name']);
                        let name = nameField ? characterData[nameField] : '未知角色';
                        let html = `<div class="bg-gray-800/50 p-3 rounded-md border border-gray-700">
                                      <h4 class="font-bold text-ph-orange mb-2 text-lg">${name}</h4>
                                      <ul class="space-y-1.5 text-sm">`;
                        for(const [key, value] of Object.entries(characterData)) {
                             if(key.toLowerCase().includes('名')) continue;
                             let formattedValue = value;
                             if (Array.isArray(value)) {
                                 formattedValue = `<ul class="list-disc list-inside ml-2">${value.map(v => `<li>${v}</li>`).join('')}</ul>`;
                             } else if (typeof value === 'object' && value !== null) {
                                const subItems = Object.entries(value).map(([sk, sv]) => `<li><strong>${sk}:</strong> ${sv}</li>`).join('');
                                formattedValue = `<ul class="list-disc list-inside ml-2">${subItems}</ul>`;
                             }
                             html += `<li class="text-gray-300"><strong class="font-semibold text-white">${key}:</strong> ${formattedValue}</li>`;
                        }
                        html += `</ul></div>`;
                        this.elements.cast.innerHTML += html;
                    });
                }

                renderComments(rootData) {
                    const commentsField = this.findField(rootData, ['评论区', 'comment', '选项']);
                    if (!commentsField || !rootData[commentsField]) {
                         this.elements.comments.innerHTML = `<p class="p-4 text-center text-gray-500">无行动选项。</p>`;
                         return;
                    }

                    const commentsArray = Array.isArray(rootData[commentsField]) ? rootData[commentsField] : (rootData[commentsField].评论 ? rootData[commentsField].评论 : []);

                    this.elements.comments.innerHTML = '';
                    commentsArray.forEach(item => {
                         const commentData = item.评论 || item.comment || item;
                         if (typeof commentData !== 'object' || commentData === null) return;

                         const userField = this.findField(commentData, ['用户', 'user']);
                         const contentField = this.findField(commentData, ['内容', 'content']);
                         if(!userField || !contentField) return;

                         const user = commentData[userField];
                         const content = commentData[contentField];
                         const li = document.createElement('div');
                         li.className = 'p-3 comment-item';
                         li.setAttribute('data-action', content);
                         li.innerHTML = `<div class="flex items-start space-x-3">
                                <i class="fa fa-user-circle text-2xl text-gray-500 mt-1"></i>
                                <div>
                                    <p class="font-bold text-ph-orange">${user}</p>
                                    <p class="text-white">${content}</p>
                                </div>
                            </div>`;
                         this.elements.comments.appendChild(li);
                    });
                }

                setupEventListeners() {
                    this.elements.comments.addEventListener('click', (e) => {
                        const item = e.target.closest('[data-action]');
                        if(item) {
                            triggerQuickReply(item.getAttribute('data-action'));
                        }
                    });
                }

                formatTime(timeStr) {
                    return typeof timeStr === 'string' ? timeStr.replace(/[⏰📍]/gu, '').trim() : '';
                }

                handleError(error) {
                    console.error('PornhubRenderer Error:', error);
                    const container = document.querySelector('.player-container') || document.body;
                    container.innerHTML = `<div class="bg-red-900 border border-red-700 text-red-300 p-4 rounded-lg m-4"><strong>渲染错误:</strong> ${error.message}</div>`;
                }
            }
            new PornhubRenderer('yaml-data-source').init();
        });
    </script>
</body>
</html>
